    "settings.harness.title": "Stop wasted tokens",
    "settings.harness.alerts": "Ledger alerts: late landings and stale branches",
    "settings.harness.alertsHint": "When on, the ledger checks work records against git once a minute. It tells the run's coordinator about reports with no verification for over 2 hours, verified work with no merge record, and merged work whose folder is left over; it tells the worker when its branch is far behind main or would conflict on merge. It only tells — it never merges, deletes or pushes.",
    "settings.harness.alertsOn": "On",
    "settings.harness.alertsOff": "Off",
    "settings.harness.prompts": "When a summoned worker asks for permission",
    "settings.harness.promptsHint": "“Ask” keeps today's behaviour: the worker waits at the permission prompt for a person's answer. “Refuse and carry on” refuses that call at once, tells the model and continues the turn; several refusals in a row end the turn. A call you might have allowed is refused, and in exchange the worker never stands still. The window launches workers so they do not stop to ask, so most agents, Codex and zo among them, never open a permission prompt; this setting reaches the Claude Code workers that still ask (Claude Code 2.1.319 or later). Panes you open yourself are not changed, and a worker already running follows it from its next launch.",
    "settings.harness.promptsAsk": "Ask",
    "settings.harness.promptsRefuse": "Refuse and carry on",
    "settings.harness.peerMail": "Mail between agent panes",
    "settings.harness.peerMailHint": "When on, the agent panes you open in this window can send ledger letters to other panes of the same project; panes find each other with zerocode-orc peers. A letter wakes a pane at most three times after you last typed in that pane, and a reply wakes nobody. A pane of another project cannot be written to, and a letter for a worker goes to its run's coordinator. When off, new letters are refused and letters already sent can still be read.",
    "settings.harness.peerMailOn": "On",
    "settings.harness.peerMailOff": "Off",
    "settings.harness.about": "The window watches the workers that are working. When it sees the same work repeated or the cost climbing it tells you, and it can stop a worker before the budget is passed. The verdict and what it was read from show on each worker's line on the task board.",
    "settings.harness.mode": "Worker continue check",
    "settings.harness.modeHint": "Notify only: shows the verdict on the board and tells the coordinator; no worker is ended. Stop: saves the worker's work as a restore point and ends that worker before the budget is passed.",
    "settings.harness.modeOff": "Off",
    "settings.harness.modeNotify": "Notify only",
    "settings.harness.modeStop": "Stop before the budget is passed",
    "settings.harness.taskBudget": "Budget for one task (USD)",
    "settings.harness.taskBudgetHint": "Counted at API prices. Leave it empty for no budget.",
    "settings.harness.dayBudget": "Budget for a day (USD)",
    "settings.harness.dayBudgetHint": "All workers together, counted over a rolling 24 hours. Leave it empty for no budget.",
    "settings.harness.launchesTitle": "Agent call limits",
    "settings.harness.launchesAbout": "Calls the window makes to an agent's CLI on your behalf (commit message drafts, login renewals and the like) are counted as one person's. A CLI that hits its limit (429) rests for a while, and the same job is run only once. Leave a field empty for no limit.",
