    "computerUse.shareRequiredAbout": "Block actions in apps that have not been shared. Silence does not allow actions. Viewing keeps its existing rules.",
    "computerUse.deskGuard": "Stop zo from moving the screen with shell commands",
    "computerUse.deskGuardAbout": "In this window's zo panes, when the model sends a shell command that moves the screen itself — cliclick or a System Events script, for example — zo refuses it in every permission mode and sends the model back to the Computer tool. It catches a command only when that name shows in the command's text, and it does not apply to Claude Code or Codex panes. A change applies to zo sessions started after it; a session already running may keep the value it read.",
    "computerUse.deskGuardUnreadable": "The zo settings file could not be read, so there is no telling whether this is on. Fix the file, then open this page again.",
    "computerUse.deskGuardNotBoolean": "deskGuard in the zo settings file is neither true nor false, so there is no telling whether this is on. Fix that line in the file, or remove it.",
    "computerUse.inputPolicyTitle": "Work in the background",
    "computerUse.inputPolicyAbout": "Background input is the default. Unsupported actions stop instead of falling back to foreground input. Even with the option below on, nothing borrows them on its own: an agent uses your mouse, keyboard and focus only when it says so, for work you asked for.",
