    "computerUse.generator": "Typing into fields · autopilot plans",
    "computerUse.generatorAbout": "When an agent meets an empty field, or the reflex autopilot writes a plan, a small model is asked. By default it is the login this window opens its agents with — the official CLI is run once and the account's subscription limit is spent; the login itself is never read or sent. A value already in the field is never sent.",
