    "computer.handoff.codeSend": "Send",
    "computer.handoff.codeInvalid": "Enter {{min}}–{{max}} letters or digits",
    "emulator.realPhone.consent": "An agent asks to control the real phone “{{phone}}” from inside it. Allowing it builds Appium WebDriverAgent {{tag}} on this Mac with one small patch of ours (a modified build) and installs it on the phone, signed by team “{{team}}” ({{kind}}). Xcode makes an App ID and a provisioning profile for this runner in your Apple account. Agents can then read the screen, press and type on this phone without the Mac's pointer, even while you are using it; lock the phone to stop them. They never unlock it or enter a password; a payment or transfer stays yours. This lasts for this phone until you turn it off in Settings or run phone-remove. To allow, press Done.",
    "emulator.realPhone.remove": "An agent asks to remove WebDriverAgent from “{{phone}}” and its build from this Mac, and to turn off controlling real phones. Nothing else on the phone changes. The App ID and profile Xcode made in your Apple account stay there. To allow, press Done.",
    "emulator.realPhone.androidConsent": "An agent asks to control the real Android phone “{{phone}}” over USB or wireless debugging (adb). Allowing it copies a small text helper of ours into the phone's /data/local/tmp so typing works in every language; no app is installed. Agents can then read the screen, press, swipe and type on this phone without the Mac's pointer, even while you are using it; lock the phone to stop them. They never unlock it, press its power key, change its settings, install or remove apps, or enter a password; a payment or transfer stays yours. This lasts for this phone until you turn it off in Settings or run phone-remove. To allow, press Done.",
    "emulator.realPhone.androidRemove": "An agent asks to remove this window's text helper from the Android phone “{{phone}}” and to turn off controlling it. Nothing else on the phone changes. To allow, press Done.",
    "emulator.realPhone.title": "Real phone control",
    "emulator.realPhone.about": "Agents control the phone through a modified WebDriverAgent inside it, with no Mac pointer. Only you can turn this on, phone by phone, on the card the first use shows. Agents can press even while you are using the phone; lock it to stop them. Unlocking, passwords, payments and transfers are always yours. The build makes an App ID and a profile for this runner in your Apple account. An Android phone is driven over USB debugging with no build: allowing it copies a small text helper into its /data/local/tmp, and agents never touch its power key, settings or apps.",
    "emulator.realPhone.allowed": "Allowed (turning off ends the runner)",
    "emulator.realPhone.allowedOff": "It is turned on from the card an agent shows the first time it uses the phone.",
    "emulator.realPhone.unattended": "Unattended use (keep the runner up when unused, and bring it back if it dies)",
    "emulator.realPhone.removeAll": "Remove",
    "emulator.realPhone.removeAllHint": "Turns it off and removes the runner app from connected phones and the builds from this Mac. The App ID and profile in your Apple account stay.",
    "computer.cover.ask": "Stopped: a window of “{{app}}” covers the place to press. It was not read or closed. Clear it yourself, then press Done.",
